package PROGRAMERZ;

public class LargThree {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int a=99;
		int b=6;
		int c=1;
		if(a>b && a>c) {
			System.out.println("a in big: "+a);
		}else if(b>a && b>c) {
			System.out.println("b in big: "+b);
		}else {
			System.out.println("c in big: "+c);
		}

	}

}
